    /// 运行时解码：仅供 `SchemaHistoryStore.rebuild` 执行一次，不参与迁移决策。
    public static func sql() throws -> String {
        let encoded = chunks.joined()
        guard let compressed = Data(base64Encoded: encoded) else { throw SeedError.invalidBase64 }
        var capacity = 256 * 1024
        while capacity <= 32 * 1024 * 1024 {
            var output = Data(count: capacity)
            let decoded = output.withUnsafeMutableBytes { dst -> Int in
                compressed.withUnsafeBytes { src -> Int in
                    guard let dstBase = dst.bindMemory(to: UInt8.self).baseAddress,
                          let srcBase = src.bindMemory(to: UInt8.self).baseAddress else { return 0 }
                    return compression_decode_buffer(dstBase, capacity, srcBase, compressed.count,
                                                    nil, COMPRESSION_ZLIB)
                }
            }
            if decoded > 0 {
                output.removeSubrange(decoded..<output.count)
                guard let text = String(data: output, encoding: .utf8) else { throw SeedError.invalidUTF8 }
                return text
            }
            capacity *= 2
        }
        throw SeedError.decompressionFailed
    }
}

